static inline fixed_bytes_256 fixed_bytes_256_zero(void) {
  fixed_bytes_256 result = {{0}};
  return result;
}


static inline bool eq_fixed_bytes_256(const fixed_bytes_256 op1, const fixed_bytes_256 op2) {
  return memcmp(op1.bytes, op2.bytes, 256) == 0;
}


static inline fixed_bytes_256 vector_init_fixed_bytes_256(const sail_int length_arg, const uint64_t elem) {
  (void)length_arg;
  fixed_bytes_256 result = {0};
  for (size_t i = 0; i < 256; ++i) {
    result.bytes[i] = (uint8_t)elem;
  }
  return result;
}

static inline fixed_bytes_256 undefined_vector_fixed_bytes_256(const sail_int length_arg, const uint64_t elem) {
  return vector_init_fixed_bytes_256(length_arg, elem);
}

static inline fixed_bytes_256 vector_update_fixed_bytes_256(fixed_bytes_256 value, const sail_int index, const uint64_t elem) {
  const uint64_t i = sail_int_get_ui(index);
  if (i < 256) {
    value.bytes[i] = (uint8_t)elem;
  }
  return value;
}

static inline uint64_t vector_access_fixed_bytes_256(const fixed_bytes_256 value, const sail_int index) {
  const uint64_t i = sail_int_get_ui(index);
  return i < 256 ? (uint64_t)value.bytes[i] : UINT64_C(0);
}

